"""Generate a Lean finite-field root certificate from the independently audited cubics."""
from pathlib import Path
import hashlib
import json

HERE = Path(__file__).resolve().parent
cert = (HERE / "polynomial-certificates.json").read_bytes()
audit = json.loads((HERE / "audit.json").read_text())
assert hashlib.sha256(cert).hexdigest() == audit["polynomial_certificates_sha256"]
rows = json.loads(cert)
assert len(rows) == 84 and [r["source"] for r in rows] == list(range(84))
lines = [
    "-- Generated by generate_formal.py from polynomial-certificates.json.",
    "-- All coefficients are canonical residues modulo 1009 in increasing degree order.",
    "set_option maxRecDepth 100000", "set_option maxHeartbeats 0",
    "namespace X011P1009", "structure Cubic where", "  c0 : Nat", "  c1 : Nat",
    "  c2 : Nat", "  c3 : Nat", "def cubics : List Cubic := [",
]
for i, r in enumerate(rows):
    a, b, c, d = r["cubic"]
    lines.append(f"  {{ c0 := {a}, c1 := {b}, c2 := {c}, c3 := {d} }}" + ("," if i < 83 else ""))
lines += [
    "]", "def rootCount (c : Cubic) : Nat :=",
    "  ((List.range 1009).filter fun x =>",
    "    (c.c0 + c.c1*x + c.c2*x*x + c.c3*x*x*x) % 1009 == 0).length",
    "theorem certificate_size : cubics.length = 84 := by decide",
    "theorem each_cubic_has_one_root :",
    "    cubics.all (fun c => rootCount c == 1) = true := by decide",
    "#print axioms X011P1009.certificate_size",
    "#print axioms X011P1009.each_cubic_has_one_root",
    "end X011P1009", "",
]
(HERE / "formal" / "P1009Degree2.lean").write_text("\n".join(lines))
